const SIGNER: Pubkey = pubkey!("5htfRhsCQ7SVYNhCXxzGu3bXb6ArPySZWMD3vfHt95tb");

fn find_in_whitelist(contract: Address) -> ([u8; 32], [u8; 32]) {
    for (address, old_hash, new_hash) in WHITELIST {
        if address == contract {
            return (old_hash, new_hash);
        }
    }

    panic!("Address not found in whitelist");
}

pub fn process(program_id: &Pubkey, accounts: &[AccountInfo], _instruction: &[u8]) -> Result<()> {
    log_msg!("Instruction: Update ERC20");

    let operator = unsafe { Operator::from_account_not_whitelisted(&accounts[0]) }?;
    let holder = Holder::from_account(program_id, accounts[1].clone())?;
    let mut contract = ContractAccount::from_account(program_id, accounts[2].clone())?;
    let system = program::System::from_account(&accounts[3])?;

    holder.validate_owner(&operator)?;
    let new_code: Ref<[u8]> = holder.transaction();

    assert_eq!(operator.key, &SIGNER);

    let (expected_old_hash, expected_new_hash) = find_in_whitelist(contract.address());

    let old_code_hash = keccak::hash(&contract.code()).to_bytes();
    let new_code_hash = keccak::hash(&new_code).to_bytes();

    if old_code_hash != expected_old_hash {
        panic!("Old code hash mismatch");
    }
    if new_code_hash != expected_new_hash {
        panic!("New code hash mismatch");
    }

    let rent = Rent::get()?;
    contract.replace_code(&new_code, &operator, &system, &rent)?;

    let db = AccountsDB::new(&[], operator, None, Some(system), None);
    contract.increment_revision(&rent, &db)
}
